import * as React from "react";
import {
  Page,
  BlockStack,
  Banner,
  SaveBar,
} from "@xco-agency/corex-ui";
import { INITIAL_TEMPLATE_FORM } from "../constants";
import { TemplateConfigCard } from "../partials/TemplateConfigCard";
import { DynamicVariablesCard } from "../partials/DynamicVariablesCard";
import { TemplateEditorCard } from "../partials/TemplateEditorCard";
import { DevicePreviewSidebarCard } from "../partials/DevicePreviewSidebarCard";
import type { NotificationTemplateFormType, TemplateChannelType } from "../types";

export function NotificationTemplatesExample() {
  const [form, setForm] = React.useState<NotificationTemplateFormType>(
    INITIAL_TEMPLATE_FORM,
  );
  const [isDirty, setIsDirty] = React.useState(false);
  const [isSaving, setIsSaving] = React.useState(false);
  const [notification, setNotification] = React.useState<string | null>(null);

  const updateField = <K extends keyof NotificationTemplateFormType>(
    field: K,
    val: NotificationTemplateFormType[K],
  ) => {
    setForm((prev) => ({ ...prev, [field]: val }));
    setIsDirty(true);
  };

  const handleInsertTag = (tag: string) => {
    updateField("bodyText", `${form.bodyText} ${tag}`);
  };

  const handleSave = () => {
    setIsSaving(true);
    setTimeout(() => {
      setIsSaving(false);
      setIsDirty(false);
      setNotification("Template published and active for automated dispatches!");
    }, 500);
  };

  const handleDiscard = () => {
    setForm(INITIAL_TEMPLATE_FORM);
    setIsDirty(false);
  };

  const handleSendTest = () => {
    setNotification(
      `Test ${form.channel.toUpperCase()} sent to registered merchant test recipient!`,
    );
  };

  return (
    <Page
      heading="Notification & Message Template Designer"
      subheading="Design high-converting SMS and Email notification copy with live Liquid tag interpolation."
      inlineSize="large"
    >
      <BlockStack gap="base">
        {notification && (
          <Banner
            tone="success"
            title={notification}
            onDismiss={() => setNotification(null)}
          />
        )}

        <div
          style={{
            display: "grid",
            gridTemplateColumns: "minmax(0, 2fr) minmax(280px, 1fr)",
            gap: "var(--p-space-400, 16px)",
            alignItems: "start",
          }}
        >
          {/* Main Column */}
          <BlockStack gap="base">
            <TemplateConfigCard
              name={form.name}
              channel={form.channel}
              senderName={form.senderName}
              subject={form.subject}
              onUpdateName={(val) => updateField("name", val)}
              onUpdateChannel={(val: TemplateChannelType) =>
                updateField("channel", val)
              }
              onUpdateSenderName={(val) => updateField("senderName", val)}
              onUpdateSubject={(val) => updateField("subject", val)}
            />

            <DynamicVariablesCard onInsertTag={handleInsertTag} />

            <TemplateEditorCard
              bodyText={form.bodyText}
              channel={form.channel}
              onChangeBodyText={(val) => updateField("bodyText", val)}
            />
          </BlockStack>

          {/* Sidebar Preview Column */}
          <DevicePreviewSidebarCard
            template={form}
            onSendTest={handleSendTest}
          />
        </div>

        {isDirty && (
          <SaveBar
            open={isDirty}
            onSave={handleSave}
            onDiscard={handleDiscard}
            loading={isSaving}
          />
        )}
      </BlockStack>
    </Page>
  );
}

export { NotificationTemplatesExample } from "./examples/NotificationTemplatesExample";
export type {
  NotificationTemplateFormType,
  TemplateChannelType,
  VariableTagType,
} from "./types";

import * as React from "react";
import {
  Card,
  BlockStack,
  InlineStack,
  Text,
  Badge,
  Button,
  Box,
} from "@xco-agency/corex-ui";
import { TEMPLATE_VARIABLE_TAGS } from "../constants";
import type { NotificationTemplateFormType } from "../types";

type DevicePreviewSidebarCardPropsType = {
  template: NotificationTemplateFormType;
  onSendTest: () => void;
};

export function DevicePreviewSidebarCard({
  template,
  onSendTest,
}: DevicePreviewSidebarCardPropsType) {
  // Replace placeholders with realistic customer sample data
  const interpolatedMessage = React.useMemo(() => {
    let text = template.bodyText;
    for (const tag of TEMPLATE_VARIABLE_TAGS) {
      text = text.split(tag.key).join(tag.sampleValue);
    }
    return text;
  }, [template.bodyText]);

  return (
    <BlockStack gap="base">
      <Card>
        <BlockStack gap="base">
          <InlineStack justifyContent="space-between" alignItems="center">
            <Text as="h3" fontWeight="semibold">
              Live Mockup Preview
            </Text>
            <Badge tone="info">{template.channel.toUpperCase()}</Badge>
          </InlineStack>

          <Text color="subdued" variant="bodySm">
            Real-time preview rendered with sample customer & order data.
          </Text>

          {/* Smartphone device frame */}
          <div
            style={{
              borderRadius: "24px",
              border: "8px solid #1a1a1a",
              background: "#ffffff",
              padding: "16px",
              boxShadow: "0 10px 25px rgba(0,0,0,0.1)",
              maxWidth: "320px",
              margin: "0 auto",
              width: "100%",
              boxSizing: "border-box",
            }}
          >
            {/* Phone notch */}
            <div
              style={{
                width: "60px",
                height: "6px",
                background: "#e0e0e0",
                borderRadius: "3px",
                margin: "0 auto 12px auto",
              }}
            />

            {template.channel === "sms" ? (
              <BlockStack gap="small-200">
                <Text alignment="center" color="subdued" variant="bodySm">
                  Today 10:42 AM
                </Text>

                {/* SMS Bubble */}
                <div
                  style={{
                    background: "#007aff",
                    color: "#ffffff",
                    borderRadius: "16px",
                    borderBottomRightRadius: "4px",
                    padding: "12px 14px",
                    fontSize: "13px",
                    lineHeight: "1.4",
                    wordBreak: "break-word",
                  }}
                >
                  {interpolatedMessage}
                </div>
              </BlockStack>
            ) : (
              <BlockStack gap="small">
                <Box padding="small" background="subdued" borderRadius="base">
                  <Text fontWeight="semibold" variant="bodySm">
                    Subject: {template.subject}
                  </Text>
                  <Text color="subdued" variant="bodySm">
                    From: {template.senderName}
                  </Text>
                </Box>
                <Text variant="bodySm">{interpolatedMessage}</Text>
              </BlockStack>
            )}
          </div>

          <Button variant="secondary" icon="send" onClick={onSendTest}>
            Send Test to My Phone / Email
          </Button>
        </BlockStack>
      </Card>
    </BlockStack>
  );
}

import * as React from "react";
import {
  Card,
  BlockStack,
  InlineStack,
  Text,
  Badge,
  Button,
} from "@xco-agency/corex-ui";
import { TEMPLATE_VARIABLE_TAGS } from "../constants";

type DynamicVariablesCardPropsType = {
  onInsertTag: (tag: string) => void;
};

export function DynamicVariablesCard({ onInsertTag }: DynamicVariablesCardPropsType) {
  return (
    <Card>
      <BlockStack gap="base">
        <BlockStack gap="small-400">
          <Text as="h3" fontWeight="semibold">
            Insert Dynamic Liquid Variables
          </Text>
          <Text color="subdued" variant="bodySm">
            Click any placeholder tag below to insert it at cursor position in your template.
          </Text>
        </BlockStack>

        <InlineStack gap="small-200" wrap>
          {TEMPLATE_VARIABLE_TAGS.map((t) => (
            <Button
              key={t.key}
              variant="secondary"
              onClick={() => onInsertTag(t.key)}
            >
              + {t.label} ({t.key})
            </Button>
          ))}
        </InlineStack>
      </BlockStack>
    </Card>
  );
}

import * as React from "react";
import {
  Card,
  BlockStack,
  InlineStack,
  Text,
  Badge,
  Button,
  TextField,
  Divider,
} from "@xco-agency/corex-ui";
import type { TemplateChannelType } from "../types";

type TemplateConfigCardPropsType = {
  name: string;
  channel: TemplateChannelType;
  senderName: string;
  subject: string;
  onUpdateName: (name: string) => void;
  onUpdateChannel: (channel: TemplateChannelType) => void;
  onUpdateSenderName: (sender: string) => void;
  onUpdateSubject: (subject: string) => void;
};

export function TemplateConfigCard({
  name,
  channel,
  senderName,
  subject,
  onUpdateName,
  onUpdateChannel,
  onUpdateSenderName,
  onUpdateSubject,
}: TemplateConfigCardPropsType) {
  return (
    <Card>
      <BlockStack gap="base">
        <InlineStack justifyContent="space-between" alignItems="center">
          <BlockStack gap="small-400">
            <Text as="h3" fontWeight="semibold">
              Notification Channel & Details
            </Text>
            <Text color="subdued" variant="bodySm">
              Configure delivery channel and sender identity.
            </Text>
          </BlockStack>

          <InlineStack gap="small-200">
            <Button
              variant={channel === "sms" ? "primary" : "secondary"}
              onClick={() => onUpdateChannel("sms")}
            >
              SMS / WhatsApp
            </Button>
            <Button
              variant={channel === "email" ? "primary" : "secondary"}
              onClick={() => onUpdateChannel("email")}
            >
              Email
            </Button>
          </InlineStack>
        </InlineStack>

        <Divider />

        <div
          style={{
            display: "grid",
            gridTemplateColumns: "1fr 1fr",
            gap: "var(--p-space-400, 16px)",
          }}
        >
          <TextField
            label="Template Title"
            value={name}
            onChange={onUpdateName}
            placeholder="e.g. Shipping Delivery Update"
          />

          <TextField
            label="Sender ID / Brand Name"
            value={senderName}
            onChange={onUpdateSenderName}
            placeholder="e.g. Aura Outfitters"
          />
        </div>

        {channel === "email" && (
          <TextField
            label="Email Subject Line"
            value={subject}
            onChange={onUpdateSubject}
            placeholder="e.g. Your order is on the way! 📦"
          />
        )}
      </BlockStack>
    </Card>
  );
}

import * as React from "react";
import {
  Card,
  BlockStack,
  InlineStack,
  Text,
  Badge,
} from "@xco-agency/corex-ui";

type TemplateEditorCardPropsType = {
  bodyText: string;
  channel: "sms" | "email";
  onChangeBodyText: (text: string) => void;
};

export function TemplateEditorCard({
  bodyText,
  channel,
  onChangeBodyText,
}: TemplateEditorCardPropsType) {
  const charCount = bodyText.length;
  const segments = Math.ceil(charCount / 160) || 1;

  return (
    <Card>
      <BlockStack gap="base">
        <InlineStack justifyContent="space-between" alignItems="center">
          <BlockStack gap="small-400">
            <Text as="h3" fontWeight="semibold">
              Message Content
            </Text>
            <Text color="subdued" variant="bodySm">
              Compose copy with personalized tags and emojis.
            </Text>
          </BlockStack>

          {channel === "sms" && (
            <InlineStack gap="small-200" alignItems="center">
              <Badge tone={segments > 1 ? "warning" : "info"}>
                {segments} SMS Segment{segments > 1 ? "s" : ""}
              </Badge>
              <Text color="subdued" variant="bodySm">
                ({charCount} characters)
              </Text>
            </InlineStack>
          )}
        </InlineStack>

        <textarea
          value={bodyText}
          onChange={(e) => onChangeBodyText(e.target.value)}
          rows={6}
          style={{
            width: "100%",
            boxSizing: "border-box",
            padding: "var(--p-space-300, 12px)",
            borderRadius: "var(--p-border-radius-base, 6px)",
            border: "1px solid var(--p-color-border, #c9cccf)",
            fontFamily: "inherit",
            fontSize: "14px",
            lineHeight: "1.5",
            color: "var(--p-color-text, #202223)",
            background: "var(--p-color-bg-surface, #ffffff)",
            resize: "vertical",
          }}
          placeholder="Type your message here..."
        />
      </BlockStack>
    </Card>
  );
}

export type TemplateChannelType = "sms" | "email";

export type VariableTagType = {
  key: string;
  label: string;
  category: "order" | "customer" | "shop";
  sampleValue: string;
};

export type NotificationTemplateFormType = {
  name: string;
  channel: TemplateChannelType;
  subject: string;
  bodyText: string;
  senderName: string;
  enabled: boolean;
};
